#!/usr/bin/env python3
"""
OCR Text Extraction using Llama 3.1 Model
Extracts recipient names and addresses from raw OCR text
"""

import json
import os
import sys

# Add the parent directory to the path to import ollama
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

import ollama


def create_extraction_prompt(ocr_text):
    """Create a structured prompt for the Llama model"""
    prompt = f"""You are an expert at extracting recipient information from shipping labels with OCR errors.

IMPORTANT RULES:
1. Extract ONLY the recipient name and address (NOT the sender)
2. The sender is typically "notifii llc" or "notifi llc" at "8150 sierra college blvd suite 230, roseville ca 95661" - IGNORE this
3. Handle OCR errors and typos intelligently
4. Return ONLY valid JSON in this exact format:
{{
  "recipient_name": "Full Name",
  "recipient_address": "Complete Address"
}}

OCR Text:
{ocr_text}

Extract the recipient information and return ONLY the JSON object, nothing else."""
    
    return prompt


def extract_with_llama(ocr_text, entry_id):
    """Use Llama 3.1 to extract recipient information"""
    try:
        prompt = create_extraction_prompt(ocr_text)
        
        # Call Llama 3.1 model
        response = ollama.chat(
            model='llama3.1:8b',
            messages=[
                {
                    'role': 'user',
                    'content': prompt
                }
            ]
        )
        
        # Extract the response content
        response_text = response['message']['content'].strip()
        
        # Try to parse JSON from response
        # Sometimes the model might add extra text, so we need to extract the JSON
        json_start = response_text.find('{')
        json_end = response_text.rfind('}') + 1
        
        if json_start != -1 and json_end > json_start:
            json_str = response_text[json_start:json_end]
            result = json.loads(json_str)
            
            return {
                "entry_id": entry_id,
                "recipient_name": result.get("recipient_name", ""),
                "recipient_address": result.get("recipient_address", ""),
                "status": "success"
            }
        else:
            return {
                "entry_id": entry_id,
                "recipient_name": "",
                "recipient_address": "",
                "status": "error",
                "error": "No JSON found in response"
            }
            
    except Exception as e:
        return {
            "entry_id": entry_id,
            "recipient_name": "",
            "recipient_address": "",
            "status": "error",
            "error": str(e)
        }


def read_ocr_data(file_path):
    """Read and parse the OCR data file"""
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()
    
    # Split by the delimiter
    entries = content.split('\n---\n')
    
    # Parse each entry
    parsed_entries = []
    for entry in entries:
        entry = entry.strip()
        if entry:
            # Extract entry number and text
            lines = entry.split('\n', 1)
            if len(lines) == 2:
                entry_header = lines[0].strip()
                entry_text = lines[1].strip()
                parsed_entries.append(entry_text)
    
    return parsed_entries


def main():
    """Main extraction function"""
    # File paths
    script_dir = os.path.dirname(os.path.abspath(__file__))
    input_file = os.path.join(script_dir, 'raw_ocr_data.txt')
    output_file = os.path.join(script_dir, 'extracted_results.json')
    
    print("=" * 70)
    print("OCR Text Extraction using Llama 3.1:8b")
    print("=" * 70)
    print()
    
    # Read OCR data
    print(f"Reading OCR data from: {input_file}")
    ocr_entries = read_ocr_data(input_file)
    print(f"Found {len(ocr_entries)} entries to process")
    print()
    
    # Process each entry
    results = []
    for idx, ocr_text in enumerate(ocr_entries, 1):
        print(f"Processing Entry {idx}/{len(ocr_entries)}...", end=' ')
        result = extract_with_llama(ocr_text, idx)
        results.append(result)
        
        if result['status'] == 'success':
            print("✓")
            print(f"  Name: {result['recipient_name']}")
            print(f"  Address: {result['recipient_address']}")
        else:
            print("✗")
            print(f"  Error: {result.get('error', 'Unknown error')}")
        print()
    
    # Save results
    output_data = {
        "model": "llama3.1:8b",
        "total_entries": len(results),
        "successful_extractions": sum(1 for r in results if r['status'] == 'success'),
        "entries": results
    }
    
    with open(output_file, 'w', encoding='utf-8') as f:
        json.dump(output_data, f, indent=2, ensure_ascii=False)
    
    print("=" * 70)
    print(f"Results saved to: {output_file}")
    print(f"Successfully extracted: {output_data['successful_extractions']}/{output_data['total_entries']}")
    print("=" * 70)
    
    # Print summary
    print("\n" + "=" * 70)
    print("EXTRACTION SUMMARY")
    print("=" * 70)
    for result in results:
        if result['status'] == 'success':
            print(f"\nEntry {result['entry_id']}:")
            print(f"  Recipient: {result['recipient_name']}")
            print(f"  Address: {result['recipient_address']}")


if __name__ == "__main__":
    main()
